CREATE TABLE `mobskills` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `note` varchar(255) DEFAULT NULL,
  `npcid` int(10) NOT NULL,
  `probability` int(3) unsigned NOT NULL DEFAULT '0',
  `base_damage` int(5) NOT NULL DEFAULT '0',
  `random_damage` int(5) unsigned NOT NULL DEFAULT '0',
  `range` int(3) NOT NULL DEFAULT '1' COMMENT '最大施法距離',
  `area` int(6) NOT NULL DEFAULT '0',
  `effect_id` int(6) unsigned NOT NULL DEFAULT '0',
  `is_target_effect` int(1) unsigned NOT NULL DEFAULT '0',
  `is_arrow` int(1) unsigned NOT NULL DEFAULT '0' COMMENT 'spr 指令109 是否為-1',
  `action` int(3) NOT NULL DEFAULT '18' COMMENT '使用動做',
  `mp_consume` int(3) NOT NULL DEFAULT '0' COMMENT 'MP消耗',
  `spell_count` int(3) NOT NULL DEFAULT '0' COMMENT '施放次數',
  `spell_hp_percent` int(3) NOT NULL DEFAULT '100' COMMENT '血量低於幾%施放',
  `attr` int(3) unsigned NOT NULL DEFAULT '0',
  `summonid` int(10) NOT NULL DEFAULT '0' COMMENT '招換怪物的npcid',
  `polyid` int(10) NOT NULL DEFAULT '0' COMMENT '變身ID',
  `skill_effect` int(6) NOT NULL DEFAULT '0' COMMENT '技能的效果',
  `is_skill_bind` int(1) NOT NULL DEFAULT '0' COMMENT '是否束縛目標',
  `is_skill_recall` int(1) NOT NULL DEFAULT '0' COMMENT '拉回',
  `is_skill_smoke` int(1) NOT NULL DEFAULT '0',
  `delay` int(10) NOT NULL DEFAULT '1000' COMMENT '技能延遲',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1295 DEFAULT CHARSET=utf8;

-- ----------------------------
-- Records of mobskills
-- ----------------------------

-- ----------------------------
-- Table structure for `mob_quest_week`
-- ----------------------------
DROP TABLE IF EXISTS `mob_quest_week`;
